CREATE TABLE cti_items (
    id         INTEGER PRIMARY KEY,
    feed_id    INTEGER NOT NULL REFERENCES cti_feeds (id) ON DELETE CASCADE,
    guid       TEXT    NOT NULL,
    title      TEXT    NOT NULL,
    link       TEXT    NOT NULL DEFAULT '',
    summary    TEXT    NOT NULL DEFAULT '',
    published  TEXT    NOT NULL,
    countries  TEXT    NOT NULL DEFAULT '', -- comma-separated, surrounded by commas for LIKE matching
    sectors    TEXT    NOT NULL DEFAULT '', -- idem
    created_at TEXT    NOT NULL, regulations TEXT NOT NULL DEFAULT '',
    UNIQUE (feed_id, guid)
);
INSERT INTO "cti_items" VALUES(16,1,'https://www.cert.cyber.gouv.fr/alerte/CERTFR-2026-ALE-005/','[Màj] Vulnérabilité dans Microsoft Exchange Server (15 mai 2026)','https://www.cert.cyber.gouv.fr/alerte/CERTFR-2026-ALE-005/','[Mise à jour du 11 juin 2026] Le 9 juin 2026, Microsoft a publié des versions correctives. [Publication initiale] Le 14 mai 2026, Microsoft a publié un avis de sécurité concernant la vulnérabilité CVE-2026-42897 affectant Exchange Server. Elle permet à un attaquant non authentifié de provoquer...','2026-05-15T00:00:00Z',',FR,','','2026-11-06T16:16:56Z','');
INSERT INTO "cti_items" VALUES(17,1,'https://www.cert.cyber.gouv.fr/alerte/CERTFR-2026-ALE-006/','Multiples vulnérabilités dans Sonicwall Secure Mobile Access (15 juillet 2026)','https://www.cert.cyber.gouv.fr/alerte/CERTFR-2026-ALE-006/','Le 14 juillet 2026, Sonicwall a publié un avis de sécurité concernant deux vulnérabilités affectant les Secure Mobile Access (SMA) 1000. La vulnérabilité critique CVE-2026-15409 permet une falsification de requêtes côté serveur (SSRF) de la part d''un attaquant non authentifié. La vulnérabilité...','2026-07-15T00:00:00Z',',FR,','','2026-11-06T16:16:56Z','');
INSERT INTO "cti_items" VALUES(18,1,'https://www.cert.cyber.gouv.fr/alerte/CERTFR-2026-ALE-007/','Multiples vulnérabilités dans WordPress (20 juillet 2026)','https://www.cert.cyber.gouv.fr/alerte/CERTFR-2026-ALE-007/','Le 17 juillet 2026, WordPress a publié un correctif pour deux vulnérabilités : CVE-2026-60137 : une injection SQL (SQLi) ; CVE-2026-63030 : celle-ci permet un contournement de la politique de sécurité. Un attaquant peut exploiter ces deux vulnérabilités, de manière combinée, pour obtenir une...','2026-07-20T00:00:00Z',',FR,','','2026-11-06T16:16:56Z','');
INSERT INTO "cti_items" VALUES(19,1,'https://www.cert.cyber.gouv.fr/alerte/CERTFR-2026-ALE-008/','Multiples vulnérabilités dans Microsoft Sharepoint (22 juillet 2026)','https://www.cert.cyber.gouv.fr/alerte/CERTFR-2026-ALE-008/','Le 14 juillet 2026, à l''occasion de sa mise à jour mensuelle, Microsoft a publié, entre autres, des correctifs pour deux vulnérabilités critiques affectant SharePoint. Les vulnérabilités CVE-2026-50522 et CVE-2026-58644 permettent à un attaquant non authentifié d''exécuter du code arbitraire à...','2026-07-22T00:00:00Z',',FR,','','2026-11-06T16:16:56Z','');
INSERT INTO "cti_items" VALUES(20,1,'https://www.cert.cyber.gouv.fr/alerte/CERTFR-2026-ALE-009/','Multiples vulnérabilités dans SonicWall Secure Mobile Access (02 septembre 2026)','https://www.cert.cyber.gouv.fr/alerte/CERTFR-2026-ALE-009/','Le 01 septembre 2026, SonicWall a publié un avis de sécurité concernant deux vulnérabilités affectant les Secure Mobile Access (SMA) 1000. La vulnérabilité critique CVE-2026-83548 permet une falsification de requêtes côté serveur (SSRF) de la part d''un attaquant non authentifié. La vulnérabilité...','2026-09-02T00:00:00Z',',FR,','','2026-11-06T16:16:56Z','');
INSERT INTO "cti_items" VALUES(22,1,'https://www.cert.cyber.gouv.fr/alerte/CERTFR-2026-ALE-011/','Multiples vulnérabilités dans Citrix NetScaler ADC et Gateway (28 septembre 2026)','https://www.cert.cyber.gouv.fr/alerte/CERTFR-2026-ALE-011/','**[Mise à jour du 05 octobre 2026]** Le 4 octobre 2026, Citrix a publié un avis concernant une nouvelle vulnérabilité (CVE-2026-88779) permettant un déni de service à distance. La CISA indique que cette vulnérabilité est activement exploitée. **[Mise à jour du 30 septembre 2026]** Dans un billet...','2026-09-28T00:00:00Z',',FR,US,','','2026-11-06T16:16:56Z','');
INSERT INTO "cti_items" VALUES(24,1,'https://www.cert.cyber.gouv.fr/alerte/CERTFR-2026-ALE-013/','[MàJ] Multiples vulnérabilités dans Ivanti Connect Secure (ICS) (14 octobre 2026)','https://www.cert.cyber.gouv.fr/alerte/CERTFR-2026-ALE-013/','[Mise à jour du 2 novembre 2026] Le 29 octobre 2026, Ivanti a mis à jour son avis de sécurité du 13 octobre 2026 pour ajouter deux vulnérabilités (CVE-2026-111357 et CVE-2026-118527). Celles-ci permettent à un attaquant authentifié d''élever ses privilèges et de téléverser un fichier arbitraire...','2026-10-14T00:00:00Z',',FR,',',manufacturing,','2026-11-06T16:16:56Z','');
INSERT INTO "cti_items" VALUES(25,1,'https://www.cert.cyber.gouv.fr/alerte/CERTFR-2026-ALE-014/','[Màj] Multiples vulnérabilités dans PHP (21 octobre 2026)','https://www.cert.cyber.gouv.fr/alerte/CERTFR-2026-ALE-014/','**[Mise à jour du 26 octobre 2026]** Le 23 octobre 2026, PHP a publié un avis de sécurité concernant la vulnérabilité CVE-2026-115560. Celle-ci permet une exécution de code arbitraire à distance. L''éditeur estime que les conditions d''exploitation exigent une combinaison d''options de configuration...','2026-10-21T00:00:00Z',',FR,','','2026-11-06T16:16:56Z','');
INSERT INTO "cti_items" VALUES(26,1,'https://www.cert.cyber.gouv.fr/alerte/CERTFR-2026-ALE-015/','[MàJ] Vulnérabilité dans OpenSSH (05 novembre 2026)','https://www.cert.cyber.gouv.fr/alerte/CERTFR-2026-ALE-015/','[Mise à jour du 6 novembre 2026] Cette vulnérabilité porte l''identifiant CVE-2026-123158. Alpine a publié un bulletin de sécurité (cf. section Documentation) concernant cette vulnérabilité. Le CERT-FR précise que toute installation de correctif ou modification de la configuration doit...','2026-11-05T00:00:00Z',',FR,','','2026-11-06T16:16:56Z','');
INSERT INTO "cti_items" VALUES(28,2,'https://www.cert.cyber.gouv.fr/avis/CERTFR-2026-AVI-1442/','Multiples vulnérabilités dans Ivanti Connect Secure (02 novembre 2026)','https://www.cert.cyber.gouv.fr/avis/CERTFR-2026-AVI-1442/','De multiples vulnérabilités ont été découvertes dans Ivanti Connect Secure. Elles permettent à un attaquant de provoquer une exécution de code arbitraire à distance, une élévation de privilèges et un contournement de la politique de sécurité. Ivanti indique que les vulnérabilités CVE-2026-104935,...','2026-11-02T00:00:00Z',',FR,','','2026-11-06T16:16:56Z','');
INSERT INTO "cti_items" VALUES(75,4,'/node/25749','CISA Adds One Known Exploited Vulnerability to Catalog','https://www.cisa.gov/news-events/alerts/2026/11/04/cisa-adds-one-known-exploited-vulnerability-catalog','CISA has added one new vulnerability to its Known Exploited Vulnerabilities (KEV) Catalog , based on evidence of active exploitation. CVE-2024-27834 Apple Multiple Products Improper Authentication Vulnerability This type of vulnerability is a frequent attack vector for malicious cyber actors and poses significant risks to the federal enterprise. Binding Operational Directive (BOD) 26-04: Prioritizing Security Updates Based on Risk establishes vulnerability management requirements for Federal Civilian Executive Branch (FCEB) agencies. BOD 26-04 reinforces the importance of the KEV Catalog and requires federal agencies to prioritize rapid remediation of high-risk vulnerabilities, specifically those identified by Common Vulnerabilities and Exposures (CVEs) listed in CISA’s KEV Catalog on publicly exposed assets that grant total control of the asset post-exploitation, while deferring action for lower-risk vulnerabilities. BOD 26-04 further establishes basic expectations for when agencies must check whether threat actors compromised the system before the patch was applied. While BOD 26-04 applies only to FCEB agencies, CISA encourages all organizations to adopt risk-based vulnerability management and prioritize remediation of KEV Catalog vulnerabilities . CISA will continue to add vulnerabilities to the catalog that meet the specified criteria . Aware of an exploited vulnerability not currently listed in the KEV Catalog? Submit it for potential addition through CISA’s KEV Nomination Form . Potential KEV additions must have a CVE ID, evidence of exploitation, and clear mitigation guidance.','2026-11-04T12:00:00Z',',US,','','2026-11-06T16:16:56Z','');
INSERT INTO "cti_items" VALUES(76,4,'/node/25747','CISA Adds One Known Exploited Vulnerability to Catalog','https://www.cisa.gov/news-events/alerts/2026/11/03/cisa-adds-one-known-exploited-vulnerability-catalog','CISA has added one new vulnerability to its Known Exploited Vulnerabilities (KEV) Catalog , based on evidence of active exploitation. CVE-2026-119977 WordPress Core Time-of-check Time-of-use (TOCTOU) Race Condition Vulnerability This type of vulnerability is a frequent attack vector for malicious cyber actors and poses significant risks to the federal enterprise. Binding Operational Directive (BOD) 26-04: Prioritizing Security Updates Based on Risk establishes vulnerability management requirements for Federal Civilian Executive Branch (FCEB) agencies. BOD 26-04 reinforces the importance of the KEV Catalog and requires federal agencies to prioritize rapid remediation of high-risk vulnerabilities, specifically those identified by Common Vulnerabilities and Exposures (CVEs) listed in CISA’s KEV Catalog on publicly exposed assets that grant total control of the asset post-exploitation, while deferring action for lower-risk vulnerabilities. BOD 26-04 further establishes basic expectations for when agencies must check whether threat actors compromised the system before the patch was applied. While BOD 26-04 applies only to FCEB agencies, CISA encourages all organizations to adopt risk-based vulnerability management and prioritize remediation of KEV Catalog vulnerabilities . CISA will continue to add vulnerabilities to the catalog that meet the specified criteria . Aware of an exploited vulnerability not currently listed in the KEV Catalog? Submit it for potential addition through CISA’s KEV Nomination Form . Potential KEV additions must have a CVE ID, evidence of exploitation, and clear mitigation guidance.','2026-11-03T12:00:00Z',',US,','','2026-11-06T16:16:56Z','');
INSERT INTO "cti_items" VALUES(78,4,'/node/25738','CISA Adds Two Known Exploited Vulnerabilities to Catalog','https://www.cisa.gov/news-events/alerts/2026/10/30/cisa-adds-two-known-exploited-vulnerabilities-catalog','CISA has added two new vulnerabilities to its Known Exploited Vulnerabilities (KEV) Catalog , based on evidence of active exploitation. CVE-2026-111357 Ivanti Connect Secure Missing Authentication for Critical Function Vulnerability CVE-2026-118527 Ivanti Connect Secure Generation of Predictable Numbers or Identifiers Vulnerability These types of vulnerabilities are a frequent attack vector for malicious cyber actors and pose significant risks to the federal enterprise. Binding Operational Directive (BOD) 26-04: Prioritizing Security Updates Based on Risk establishes vulnerability management requirements for Federal Civilian Executive Branch (FCEB) agencies. BOD 26-04 reinforces the importance of the KEV Catalog and requires federal agencies to prioritize rapid remediation of high-risk vulnerabilities, specifically those identified by Common Vulnerabilities and Exposures (CVEs) listed in CISA’s KEV Catalog on publicly exposed assets that grant total control of the asset post-exploitation, while deferring action for lower-risk vulnerabilities. BOD 26-04 further establishes basic expectations for when agencies must check whether threat actors compromised the system before the patch was applied. While BOD 26-04 applies only to FCEB agencies, CISA encourages all organizations to adopt risk-based vulnerability management and prioritize remediation of KEV Catalog vulnerabilities . CISA will continue to add vulnerabilities to the catalog that meet the specified criteria . Aware of an exploited vulnerability not currently listed in the KEV Catalog? Submit it for potential addition through CISA’s KEV Nomination Form . Potential KEV additions must have a CVE ID, evidence of exploitation, and clear mitigation guidance.','2026-10-30T12:00:00Z',',US,','','2026-11-06T16:16:56Z','');
INSERT INTO "cti_items" VALUES(79,4,'/node/25730','Hitachi Energy CoreTec Product','https://www.cisa.gov/news-events/ics-advisories/icsa-26-302-03','View CSAF Summary Hitachi Energy is aware of OS command injection and Dirty Frag vulnerabilities that affect CoreTec product versions listed in this document. Successful exploitation of these vulnerabilities could result in impact on confidentiality, integrity and availability of the product. Please refer to the Recommended Immediate Actions for information about the mitigation/remediation. The following versions of Hitachi Energy CoreTec Product are affected: CoreTec5 vers:CoreTec5/<=3.4.0, 5.0.0 (CVE-2026-13162, CVE-2026-43284) CoreTec4 vers:CoreTec4/<=3.4.0 (CVE-2026-13162) CVSS Vendor Equipment v3 8.8 Hitachi Energy CoreTec5 2 Vulnerabilities Improper Neutralization of Special Elements used in an OS Command (''OS Command Injection''), Write-what-where Condition Background Critical Infrastructure Sectors: Energy Countries/Areas Deployed: Worldwide Company Headquarters Location: Switzerland Vulnerabilities Expand All + CVE-2026-13162 An OS command vulnerability exists in CoreTec product that allows authenticated users with certain roles to execute arbitrary system commands with full control over the device. The vulnerability exists in the configuration daemon''s time synchronization handler, which is responsible for setting the system timezone. When processing timezone configuration updates, the daemon constructs a shell command by concatenating user-supplied input without any sanitization or validation. Read More 2 Affected Products CoreTec5 versions 3.4.0 and prior Product Status: fixed, known_affected, recommended Remediations Vendor fix Update to CoreTec5 version 5.0.0 CoreTec4 versions 3.4.0 and prior Product Status: fixed, known_affected, recommended Remediations Vendor fix Upgrade to CoreTec5 version 5.0.0 Mitigation Follow general mitigation factors Additional Metrics Relevant CWE: CWE-78 Improper Neutralization of Special Elements used in an OS Command (''OS Command Injection'') CVSS Version Base Score Base Severity Vector String 3.1 7.5 HIGH CVSS:3.1/AV:N/AC…','2026-10-29T12:00:00Z',',CH,US,',',energy,','2026-11-06T16:16:56Z','');
INSERT INTO "cti_items" VALUES(80,4,'/node/25735','CISA Adds Two Known Exploited Vulnerabilities to Catalog','https://www.cisa.gov/news-events/alerts/2026/10/29/cisa-adds-two-known-exploited-vulnerabilities-catalog','CISA has added two new vulnerabilities to its Known Exploited Vulnerabilities (KEV) Catalog , based on evidence of active exploitation. CVE-2026-97229 GitLab Community Edition and Enterprise Edition Integer Overflow or Wraparound vulnerability CVE-2026-76418 Cisco Secure Firewall ASA Software and Cisco Secure FTD Software Unchecked Return Value to NULL Pointer Dereference Vulnerability These types of vulnerabilities are a frequent attack vector for malicious cyber actors and pose significant risks to the federal enterprise. Binding Operational Directive (BOD) 26-04: Prioritizing Security Updates Based on Risk establishes vulnerability management requirements for Federal Civilian Executive Branch (FCEB) agencies. BOD 26-04 reinforces the importance of the KEV Catalog and requires federal agencies to prioritize rapid remediation of high-risk vulnerabilities, specifically those identified by Common Vulnerabilities and Exposures (CVEs) listed in CISA’s KEV Catalog on publicly exposed assets that grant total control of the asset post-exploitation, while deferring action for lower-risk vulnerabilities. BOD 26-04 further establishes basic expectations for when agencies must check whether threat actors compromised the system before the patch was applied. While BOD 26-04 applies only to FCEB agencies, CISA encourages all organizations to adopt risk-based vulnerability management and prioritize remediation of KEV Catalog vulnerabilities . CISA will continue to add vulnerabilities to the catalog that meet the specified criteria . Aware of an exploited vulnerability not currently listed in the KEV Catalog? Submit it for potential addition through CISA’s KEV Nomination Form . Potential KEV additions must have a CVE ID, evidence of exploitation, and clear mitigation guidance.','2026-10-29T12:00:00Z',',US,','','2026-11-06T16:16:56Z','');
