INSERT INTO "vulnerabilities" VALUES('CVE-2025-43892','[]','A buffer over-read vulnerability in Fortinet FortiOS 7.6.0 through 7.6.3, FortiOS 7.4.0 through 7.4.8, FortiOS 7.2 all versions, FortiOS 7.0 all versions, FortiOS 6.4 all versions may allow an authenticated remote attacker to return a portion of device memory in the redirect response via submitting …','A buffer over-read vulnerability in Fortinet FortiOS 7.6.0 through 7.6.3, FortiOS 7.4.0 through 7.4.8, FortiOS 7.2 all versions, FortiOS 7.0 all versions, FortiOS 6.4 all versions may allow an authenticated remote attacker to return a portion of device memory in the redirect response via submitting a specially crafted request.','MEDIUM','2026-07-14T16:16:42.340','2026-09-29T14:10:00.117','["https://fortiguard.fortinet.com/psirt/#5944","https://cert-portal.siemens.com/productcert/html/ssa-864900.html"]','{"id":"CVE-2025-43892","sourceIdentifier":"psirt@fortinet.com","published":"2026-07-14T16:16:42.340","lastModified":"2026-09-29T14:10:00.117","vulnStatus":"Modified","cveTags":[],"descriptions":[{"lang":"en","value":"A buffer over-read vulnerability in Fortinet FortiOS 7.6.0 through 7.6.3, FortiOS 7.4.0 through 7.4.8, FortiOS 7.2 all versions, FortiOS 7.0 all versions, FortiOS 6.4 all versions may allow an authenticated remote attacker to return a portion of device memory in the redirect response via submitting a specially crafted request."},{"lang":"es","value":"Una vulnerabilidad de lectura excesiva de búfer en Fortinet FortiOS 7.6.0 hasta 7.6.3, FortiOS 7.4.0 hasta 7.4.8, FortiOS 7.2 todas las versiones, FortiOS 7.0 todas las versiones, FortiOS 6.4 todas las versiones puede permitir a un atacante remoto autenticado devolver una porción de la memoria del dispositivo en la respuesta de redirección mediante el envío de una solicitud especialmente diseñada."}],"affected":[{"source":"psirt@fortinet.com","affectedData":[{"vendor":"Fortinet","product":"FortiOS","defaultStatus":"unaffected","cpes":["cpe:2.3:o:forti