INSERT INTO "vulnerabilities" VALUES('CVE-2025-62826','[]','An Improper Neutralization of CRLF Sequences in HTTP Headers (''HTTP Response Splitting'') vulnerability [CWE-113] vulnerability in Fortinet FortiOS 7.6.0 through 7.6.4, FortiOS 7.4 all versions, FortiOS 7.2 all versions, FortiProxy 7.6.0 through 7.6.4, FortiProxy 7.4 all versions, FortiProxy 7.2 all …','An Improper Neutralization of CRLF Sequences in HTTP Headers (''HTTP Response Splitting'') vulnerability [CWE-113] vulnerability in Fortinet FortiOS 7.6.0 through 7.6.4, FortiOS 7.4 all versions, FortiOS 7.2 all versions, FortiProxy 7.6.0 through 7.6.4, FortiProxy 7.4 all versions, FortiProxy 7.2 all versions may allow an attacker able to intercept and modify a user''s captive portal authentication request to inject arbitrary headers via crafted HTTP requests.','LOW','2026-07-14T16:16:42.850','2026-09-29T15:10:00.193','["https://fortiguard.fortinet.com/psirt/FG-IR-26-153","https://cert-portal.siemens.com/productcert/html/ssa-864900.html"]','{"id":"CVE-2025-62826","sourceIdentifier":"psirt@fortinet.com","published":"2026-07-14T16:16:42.850","lastModified":"2026-09-29T15:10:00.193","vulnStatus":"Modified","cveTags":[],"descriptions":[{"lang":"en","value":"An Improper Neutralization of CRLF Sequences in HTTP Headers (''HTTP Response Splitting'') vulnerability [CWE-113] vulnerability in Fortinet FortiOS 7.6.0 through 7.6.4, FortiOS 7.4 all versions, FortiOS 7.2 all versions, FortiProxy 7.6.0 through 7.6.4, FortiProxy 7.4 all versions, FortiProxy 7.2 all versions may allow an attacker able to intercept and modify a user''s captive portal authentication request to inject arbitrary headers via crafted HTTP requests."},{"lang":"es","value":"Una vulnerabilidad de neutralización incorrecta de secuencias CRLF en encabezados HTTP (''División de respuesta HTTP'') [CWE-113] vulnerabilidad en Fortinet FortiOS 7.6.0 hasta 7.6.4, FortiOS 7.4 todas las versiones, FortiOS 7.2 todas las versiones, FortiProxy 7.6.0 hasta 7.6.4,